# SPDX-License-Identifier: MIT
# Copyright (c) 2026 Mark Schlosser
#
# The README shipped in the release zip: the repo README cut down to what a
# player needs (its intro plus KEEP sections, in that order) and a pointer
# to the full documentation. Generated by make release, so it never drifts.
# Fails if a KEEP section is missing, or if a kept relative link points at a
# file the zip does not contain.
#
# Usage: release_readme.py README.md OUT

import re
import sys

KEEP = ['Install', 'Controls', 'Compatibility', 'Credits', 'Licence']
IN_ZIP = {'LICENSE', 'NOTICE'}
FOOTER = ('Full documentation, source and issue tracker:\n'
          'https://github.com/Wenwald/gamebub-2600\n')


def main(argv):
    if len(argv) != 2:
        print('usage: release_readme.py README.md OUT')
        return 2
    with open(argv[0]) as f:
        text = f.read()
    parts = re.split(r'(?m)^## ', text)
    intro, sections = parts[0], {}
    for p in parts[1:]:
        title = p.split('\n', 1)[0].strip()
        sections[title] = '## ' + p
    missing = [k for k in KEEP if k not in sections]
    if missing:
        raise SystemExit('README.md: section(s) %s not found; update KEEP in %s'
                         % (', '.join(missing), __file__))
    out = intro + ''.join(sections[k].rstrip('\n') + '\n\n' for k in KEEP) + FOOTER
    bad = [l for l in re.findall(r'\]\(([^)]+)\)', out)
           if not re.match(r'https?://', l) and l not in IN_ZIP]
    if bad:
        raise SystemExit('release README links to files not in the zip: %s' % ', '.join(bad))
    with open(argv[1], 'w') as f:
        f.write(out)
    print('wrote %s: %s' % (argv[1], ', '.join(KEEP)))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
